        // Performance Options
        {"-j", "--threads", "Number of worker threads", "<count>", true, OptionCategory::PERFORMANCE},
        {"-b", "--benchmark", "Run performance benchmarks", "", false, OptionCategory::PERFORMANCE},

        // Debugging Options
        {"-q", "--quiet", "Suppress non-essential output", "", false, OptionCategory::DEBUGGING},
        {"-V", "--verbose", "Increase verbosity level", "", false, OptionCategory::DEBUGGING},

        // Miscellaneous
        {"", "--dry-run", "Simulate execution without changes", "", false, OptionCategory::MISC}
    };

    std::map<std::string, std::string> parsedOptions_;
    std::vector<std::string> positionalArgs_;

public:
    void printHelp(const std::string& programName) const {
        const int flagWidth = 25;
        const int descWidth = 50;

        std::cout << "Usage: " << programName << " [options] [arguments]\n\n";

        std::map<OptionCategory, std::string> categoryNames = {
            {OptionCategory::CORE, "Core Options"},
            {OptionCategory::INPUT_OUTPUT, "Input/Output"},
            {OptionCategory::OPERATION_MODE, "Operation Modes"},
            {OptionCategory::PERFORMANCE, "Performance"},
            {OptionCategory::DEBUGGING, "Debugging"},
            {OptionCategory::MISC, "Miscellaneous"}
        };

        for (const auto& [category, name] : categoryNames) {
            std::cout << name << ":\n";
            for (const auto& opt : options_) {
                if (opt.category == category) {
                    std::string flagDisplay;
                    if (!opt.shortFlag.empty() && !opt.longFlag.empty()) {
                        flagDisplay = opt.shortFlag + ", " + opt.longFlag;
                    } else if (!opt.shortFlag.empty()) {
                        flagDisplay = opt.shortFlag;
                    } else {
                        flagDisplay = opt.longFlag;
                    }

                    if (opt.requiresArgument) {
                        flagDisplay += " " + opt.argument;
                    }

                    std::cout << "  " << std::left << std::setw(flagWidth) << flagDisplay
                              << std::setw(descWidth) << opt.description << "\n";
                }
            }
            std::cout << "\n";
        }

        std::cout << "Examples:\n"
                  << "  " << programName << " -i input.txt -o output.txt\n"
                  << "  " << programName << " --config settings.cfg --threads 4\n";
    }

    void parse(int argc, char* argv[]) {
        for (int i = 1; i < argc; ) {
            std::string arg = argv[i];

            if (arg[0] == '-') {  // It's an option
                auto it = std::find_if(options_.begin(), options_.end(),
                    [&arg](const CommandOption& opt) {
                        return opt.shortFlag == arg || opt.longFlag == arg;
                    });

                if (it == options_.end()) {
                    throw std::runtime_error("Unknown option: " + arg);
                }

                if (it->requiresArgument) {
                    if (i + 1 >= argc) {
                        throw std::runtime_error("Option " + arg + " requires an argument");
                    }
                    parsedOptions_[it->longFlag.empty() ? it->shortFlag : it->longFlag] = argv[i+1];
                    i += 2;
                } else {
                    parsedOptions_[it->longFlag.empty() ? it->shortFlag : it->longFlag] = "";
                    i += 1;
                }
            } else {  // It's a positional argument
                positionalArgs_.push_back(arg);
                i += 1;
            }
        }

        // Handle special options
        if (hasOption("--help") || hasOption("-h")) {
            printHelp(argv[0]);
            exit(0);
        }

        if (hasOption("--version") || hasOption("-v")) {
            std::cout << "Version 1.0.0\n";
            exit(0);
        }
    }

    bool hasOption(const std::string& option) const {
        return parsedOptions_.find(option) != parsedOptions_.end();
    }

    std::string getOptionValue(const std::string& option) const {
        auto it = parsedOptions_.find(option);
        if (it == parsedOptions_.end()) {
            throw std::runtime_error("Option not found: " + option);
        }
        return it->second;
    }

    const std::vector<std::string>& getPositionalArgs() const {
        return positionalArgs_;
    }
};

