using OptionValue = std::variant<std::monostate, std::string, int, double, bool>;

enum class OptionCategory {
    CORE,
    INPUT_OUTPUT,
    OPERATION_MODE,
    PERFORMANCE,
    DEBUGGING,
    MISC
};

struct CommandOption {
    std::vector<std::string> flags;
    std::string description;
    std::string argumentName;
    OptionValue defaultValue;
    bool isRequired;
    OptionCategory category;

    // For help formatting
    std::string getFlagsFormatted() const {
        std::string result;
        for (size_t i = 0; i < flags.size(); ++i) {
            if (i != 0) result += ", ";
            result += flags[i];
            if (!argumentName.empty()) {
                result += " " + argumentName;
            }
        }
        return result;
    }
};

class CommandLineParser {
private:
    std::vector<CommandOption> options_;
    std::map<std::string, OptionValue> parsedOptions_;
    std::vector<std::string> positionalArgs_;
    std::string programName_;
    std::string programDescription_;

    // Helper for type conversion
    template<typename T>
    T convertValue(const std::string& valueStr) const {
        if constexpr (std::is_same_v<T, std::string>) {
            return valueStr;
        } else if constexpr (std::is_same_v<T, int>) {
            return std::stoi(valueStr);
        } else if constexpr (std::is_same_v<T, double>) {
            return std::stod(valueStr);
        } else if constexpr (std::is_same_v<T, bool>) {
            if (valueStr == "true" || valueStr == "1") return true;
            if (valueStr == "false" || valueStr == "0") return false;
            throw std::runtime_error("Invalid boolean value");
        } else {
            static_assert(!sizeof(T), "Unsupported type");
        }
    }

public:
    CommandLineParser(std::string description = "") 
        : programDescription_(std::move(description)) {
        // Core options
        addOption({{"-h", "--help"}, "Show this help message", "", {}, false, OptionCategory::CORE});
        addOption({{"-v", "--version"}, "Show version information", "", {}, false, OptionCategory::CORE});
    }

    void addOption(CommandOption option) {
        options_.push_back(std::move(option));
    }

    void parse(int argc, char* argv[]) {
        programName_ = argv[0];
        positionalArgs_.clear();
        parsedOptions_.clear();

        for (int i = 1; i < argc; ) {
            std::string arg = argv[i];

            if (arg[0] == '-') { // It's an option
                bool optionFound = false;
                for (const auto& opt : options_) {
                    auto it = std::find(opt.flags.begin(), opt.flags.end(), arg);
                    if (it != opt.flags.end()) {
                        if (!opt.argumentName.empty()) {
                            if (i + 1 >= argc) {
                                throw std::runtime_error("Option " + arg + " requires an argument");
                            }
                            parsedOptions_[opt.flags[0]] = argv[i+1];
                            i += 2;
                        } else {
                            parsedOptions_[opt.flags[0]] = true;
                            i += 1;
                        }
                        optionFound = true;
                        break;
                    }
                }

                if (!optionFound) {
                    throw std::runtime_error("Unknown option: " + arg);
                }
            } else { // Positional argument
                positionalArgs_.push_back(arg);
                i += 1;
            }
        }

