            if (value) {
                // Convert environment variable name to corresponding flag
                std::string flag = convertEnvToFlag(envVar);
                environmentOverrides_[flag] = value;
            }
        }
    }

    // Convert environment variable name to command-line flag
    std::string convertEnvToFlag(const std::string& envVar) const {
        std::string flag = "--" + 
            boost::algorithm::to_lower_copy(
                boost::algorithm::replace_all_copy(
                    envVar.substr(4), "_", "-"
                )
            );
        return flag;
    }

