    T convertValue(const std::variant<std::monostate, std::string, int, double, bool>& value) const {
        try {
            if (std::holds_alternative<std::monostate>(value)) {
                return T{};
            }

            if constexpr (std::is_same_v<T, std::string>) {
                return std::visit([](auto&& arg) -> std::string {
                    using U = std::decay_t<decltype(arg)>;
                    if constexpr (std::is_same_v<U, std::string>) {
                        return arg;
                    } else if constexpr (std::is_arithmetic_v<U>) {
                        return std::to_string(arg);
                    } else {
                        return "";
                    }
                }, value);
            } else if constexpr (std::is_arithmetic_v<T>) {
                return std::visit([](auto&& arg) -> T {
                    using U = std::decay_t<decltype(arg)>;
                    if constexpr (std::is_arithmetic_v<U>) {
                        return static_cast<T>(arg);
                    } else if constexpr (std::is_same_v<U, std::string>) {
                        if constexpr (std::is_integral_v<T>) {
                            return std::stoi(arg);
                        } else {
                            return std::stod(arg);
                        }
                    } else {
                        return T{};
                    }
                }, value);
            } else if constexpr (std::is_same_v<T, bool>) {
                return std::visit([](auto&& arg) -> bool {
                    using U = std::decay_t<decltype(arg)>;
                    if constexpr (std::is_same_v<U, bool>) {
                        return arg;
                    } else if constexpr (std::is_same_v<U, std::string>) {
                        return arg == "true" || arg == "1";
                    } else {
                        return false;
                    }
                }, value);
            }
        } catch (const std::exception& e) {
            log(0, "Value conversion error: " + std::string(e.what()));
            throw std::runtime_error("Invalid value conversion");
        }
