// Configuration file handling using JSON
void loadConfigFile(const std::string& path) {
    try {
        if (!std::filesystem::exists(path)) {
            throw std::runtime_error("Config file not found: " + path);
        }

        std::ifstream file(path);
        nlohmann::json config;
        file >> config;

        for (auto& [key, value] : config.items()) {
            std::string flag = "--" + key;

            // Find corresponding option
            auto optIt = std::find_if(options_.begin(), options_.end(),
                [&flag](const OptionDefinition& opt) {
                    return std::find(opt.flags.begin(), opt.flags.end(), flag) != opt.flags.end();
                });

            if (optIt != options_.end()) {
                // Convert JSON value to appropriate type
                if (value.is_string()) {
                    parsedValues_[flag] = value.get<std::string>();
                } else if (value.is_number_integer()) {
                    parsedValues_[flag] = value.get<int>();
                } else if (value.is_number_float()) {
                    parsedValues_[flag] = value.get<double>();
                } else if (value.is_boolean()) {
                    parsedValues_[flag] = value.get<bool>();
                }
            }
        }

        log(1, "Loaded configuration from: " + path);
    } catch (const std::exception& e) {
        log(0, "Config load error: " + std::string(e.what()));
        throw;
    }
