    std::cout << "\n\n";

    if (!programDescription_.empty()) {
        std::cout << programDescription_ << "\n\n";
    }

    // Group options by category
    std::map<std::string, std::vector<const OptionDefinition*>> categorizedOptions;
    for (const auto& opt : options_) {
        categorizedOptions[opt.category].push_back(&opt);
    }

    // Print options by category
    for (const auto& [category, options] : categorizedOptions) {
        std::cout << category << ":\n";
        for (const auto& opt : options) {
            std::string flags = opt->flags[0];
            if (opt->flags.size() > 1) {
                flags += ", " + opt->flags[1];
            }

            if (!opt->argumentName.empty()) {
                flags += " " + opt->argumentName;
            }

            std::cout << "  " << std::left << std::setw(flagWidth) << flags
                      << std::setw(descWidth) << opt->description;

            if (!std::holds_alternative<std::monostate>(opt->defaultValue)) {
                std::cout << " [default: ";
                std::visit([&](auto&& arg) {
                    using T = std::decay_t<decltype(arg)>;
                    if constexpr (!std::is_same_v<T, std::monostate>) {
                        if constexpr (std::is_same_v<T, bool>) {
                            std::cout << (arg ? "true" : "false");
                        } else {
                            std::cout << arg;
                        }
                    }
                }, opt->defaultValue);
                std::cout << "]";
            }

            if (opt->isRequired) {
                std::cout << " (required)";
            }

            std::cout << "\n";
        }
        std::cout << "\n";
    }

    // Print subcommands if any
    if (!subcommands_.empty()) {
        std::cout << "Commands:\n";
        for (const auto& cmd : subcommands_) {
            std::cout << "  " << std::left << std::setw(flagWidth) << cmd.name
                      << std::setw(descWidth) << cmd.description << "\n";
        }
        std::cout << "\n";
    }

    std::cout << "Examples:\n";
    std::cout << "  " << programName_ << " --input data.txt --output results.txt\n";
    if (!subcommands_.empty()) {
        std::cout << "  " << programName_ << " process --config settings.json\n";
    }
}

