// Custom type conversion and validation
template<typename T>
class TypeConverter {
public:
    // Custom parsing for complex types
    static T parse(const std::string& input) {
        if constexpr (std::is_enum_v<T>) {
            return parseEnum(input);
        } else if constexpr (std::is_same_v<T, std::filesystem::path>) {
            return parseFilePath(input);
        } else if constexpr (std::is_same_v<T, std::vector<std::string>>) {
            return parseSeparatedList(input);
        } else {
            // Fallback to standard conversion
            return convertStandardType<T>(input);
        }
    }

private:
    // Enum parsing with string mapping
    static T parseEnum(const std::string& input) {
        static const std::map<std::string, T> enumMap = {
            // Define enum string mappings
            {"read", LogLevel::READ},
            {"write", LogLevel::WRITE},
            // ...
        };

        auto it = enumMap.find(input);
        if (it != enumMap.end()) {
            return it->second;
        }
        throw std::runtime_error("Invalid enum value: " + input);
    }

    // Path validation
    static std::filesystem::path parseFilePath(const std::string& input) {
        std::filesystem::path path(input);

        // Additional path validations
        if (!std::filesystem::exists(path)) {
            throw std::runtime_error("Path does not exist: " + input);
        }

        return path;
    }

    // Comma-separated list parsing
    static std::vector<std::string> parseSeparatedList(const std::string& input) {
        std::vector<std::string> result;
        std::stringstream ss(input);
        std::string item;

        while (std::getline(ss, item, ',')) {
            // Trim whitespace
            item.erase(0, item.find_first_not_of(" "));
            item.erase(item.find_last_not_of(" ") + 1);
            result.push_back(item);
        }

        return result;
    }

    // Standard type conversion with additional checks
    template<typename U>
    static U convertStandardType(const std::string& input) {
        try {
            if constexpr (std::is_same_v<U, int>) {
                return std::stoi(input);
            } else if constexpr (std::is_same_v<U, double>) {
                return std::stod(input);
            } else if constexpr (std::is_same_v<U, bool>) {
                return parseBooleanValue(input);
            } else {
                return static_cast<U>(input);
            }
        } catch (const std::exception& e) {
            throw std::runtime_error("Conversion error: " + std::string(e.what()));
        }
    }

    // Advanced boolean parsing
    static bool parseBooleanValue(const std::string& input) {
        static const std::set<std::string> trueValues = {
            "true", "yes", "1", "on", "enable", "enabled"
        };
        static const std::set<std::string> falseValues = {
            "false", "no", "0", "off", "disable", "disabled"
        };

        std::string lowercaseInput = input;
        std::transform(lowercaseInput.begin(), lowercaseInput.end(), 
                       lowercaseInput.begin(), ::tolower);

        if (trueValues.count(lowercaseInput)) return true;
        if (falseValues.count(lowercaseInput)) return false;

        throw std::runtime_error("Invalid boolean value: " + input);
    }
};

