class ValidationRules {
public:
    // Range validation
    template<typename T>
    static auto inRange(T min, T max) {
        return [min, max](const T& value) {
            return value >= min && value <= max;
        };
    }

    // Regex validation
    static auto matchesPattern(const std::string& pattern) {
        std::regex re(pattern);
        return [re](const std::string& value) {
            return std::regex_match(value, re);
        };
    }

    // File/directory existence
    static auto fileExists() {
        return [](const std::filesystem::path& path) {
            return std::filesystem::exists(path) && 
                   std::filesystem::is_regular_file(path);
        };
    }

    // Composite validation
    template<typename... Validators>
    static auto all(Validators... validators) {
        return [validators...](const auto& value) {
            return (validators(value) && ...);
        };
    }
};

