class SubcommandManager {
private:
    struct Subcommand {
        std::string name;
        std::string description;
        std::function<void()> handler;
        std::vector<CommandOption> options;
    };

    std::map<std::string, Subcommand> subcommands_;
    std::string currentSubcommand_;

public:
    void addSubcommand(
        const std::string& name,
        const std::string& description,
        std::function<void()> handler,
        const std::vector<CommandOption>& options = {}
    ) {
        subcommands_[name] = {name, description, handler, options};
    }

    void parse(int argc, char* argv[]) {
        if (argc < 2) return;

        std::string potentialCmd = argv[1];
        if (subcommands_.count(potentialCmd)) {
            currentSubcommand_ = potentialCmd;

            // Create a new parser for subcommand options
            CommandLineParser subParser;
            for (const auto& opt : subcommands_[potentialCmd].options) {
                subParser.addOption(opt);
            }

            // Parse remaining arguments
            subParser.parse(argc - 1, argv + 1);
        }
    }

    void execute() {
        if (!currentSubcommand_.empty()) {
            subcommands_[currentSubcommand_].handler();
        }
    }

    void printHelp() const {
        std::cout << "Available commands:\n";
        for (const auto& [name, cmd] : subcommands_) {
            std::cout << "  " << std::left << std::setw(20) << name
                      << cmd.description << "\n";
        }
    }
};

