class AsyncCommandProcessor {
private:
    std::vector<std::future<void>> tasks_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool shutdown_ = false;

public:
    template<typename Func>
    void submitCommand(Func&& command) {
        std::lock_guard<std::mutex> lock(mutex_);
        tasks_.emplace_back(std::async(std::launch::async, 
            [this, command = std::forward<Func>(command)]() {
                try {
                    command();
                } catch (const std::exception& e) {
                    std::cerr << "Command failed: " << e.what() << std::endl;
                }
            }));
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            shutdown_ = true;
        }
        cv_.notify_all();

        for (auto& task : tasks_) {
            if (task.valid()) {
                task.wait();
            }
        }
    }

    void processCommands(CommandQueue& queue) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this, &queue]() {
                return shutdown_ || !queue.empty();
            });

            if (shutdown_) break;

            auto command = queue.pop();
            lock.unlock();

            submitCommand(command);
        }
    }
};

