// Plugin interface
class CommandPlugin {
public:
    virtual ~CommandPlugin() = default;
    virtual std::string getName() const = 0;
    virtual std::string getDescription() const = 0;
    virtual void registerOptions(CommandLineParser& parser) = 0;
    virtual void execute(const CommandLineParser& parser) = 0;
};

// Plugin manager
class PluginManager {
private:
    std::vector<std::shared_ptr<CommandPlugin>> plugins_;
    std::unordered_map<std::string, std::shared_ptr<CommandPlugin>> commandMap_;

public:
    void registerPlugin(std::shared_ptr<CommandPlugin> plugin) {
        plugins_.push_back(plugin);
        commandMap_[plugin->getName()] = plugin;
    }

    void registerAllOptions(CommandLineParser& parser) {
        for (const auto& plugin : plugins_) {
            plugin->registerOptions(parser);
        }
    }

    bool executeCommand(const std::string& name, const CommandLineParser& parser) {
        auto it = commandMap_.find(name);
        if (it != commandMap_.end()) {
            it->second->execute(parser);
            return true;
        }
        return false;
    }

    void printAvailableCommands() const {
        std::cout << "Available commands:\n";
        for (const auto& [name, plugin] : commandMap_) {
            std::cout << "  " << std::left << std::setw(20) << name
                      << plugin->getDescription() << "\n";
        }
    }
};

