        parser_.addOption({"--help"}, "Show help message");
    }

    int run(int argc, char* argv[]) {
        try {
            // First parse to get the command name
            parser_.parse(argc, argv);

            if (parser_.get<bool>("--help")) {
                showHelp();
                return 0;
            }

            // Get the command name from positional arguments
            auto args = parser_.getPositionalArgs();
            if (args.empty()) {
                showHelp();
                return 1;
            }

            // Re-parse with plugin options
            pluginManager_.registerAllOptions(parser_);
            parser_.parse(argc, argv);

            // Execute the command
            if (!pluginManager_.executeCommand(args[0], parser_)) {
                std::cerr << "Unknown command: " << args[0] << "\n";
                showHelp();
                return 1;
            }

        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << "\n";
            return 1;
        }
        return 0;
    }

private:
    void showHelp() {
        pluginManager_.printAvailableCommands();
        parser_.printHelp();
    }
};
