### 3. State Machine for Complex Command Flows

```cpp
// State machine for multi-step commands
class CommandStateMachine {
public:
    enum class State {
        INITIAL,
        PARSING,
        VALIDATING,
        EXECUTING,
        COMPLETED,
        ERROR
    };

    struct Context {
        CommandLineParser parser;
        std::any customData;
    };

    using TransitionHandler = std::function<void(State, State, Context&)>;

private:
    State currentState_ = State::INITIAL;
    std::map<std::pair<State, State>, TransitionHandler> transitions_;
    Context context_;

public:
    void addTransition(State from, State to, TransitionHandler handler) {
        transitions_[{from, to}] = handler;
    }

    void transitionTo(State newState) {
        auto key = std::make_pair(currentState_, newState);
        if (transitions_.count(key)) {
            transitions_[key](currentState_, newState, context_);
        }
        currentState_ = newState;
    }

    void process(int argc, char* argv[]) {
        try {
            transitionTo(State::PARSING);
            context_.parser.parse(argc, argv);

            transitionTo(State::VALIDATING);
            context_.parser.validate();

            transitionTo(State::EXECUTING);
            executeCommand();

            transitionTo(State::COMPLETED);
        } catch (const std::exception& e) {
            context_.customData = std::string(e.what());
            transitionTo(State::ERROR);
        }
    }

    State getCurrentState() const { return currentState_; }
    Context& getContext() { return context_; }

private:
    void executeCommand() {
        if (context_.parser.hasSubcommand()) {
            context_.parser.executeSubcommand();
        }
    }
};

// Usage example
void setupCommandStateMachine(CommandStateMachine& sm) {
    // Add transition handlers
    sm.addTransition(
        CommandStateMachine::State::INITIAL,
        CommandStateMachine::State::PARSING,
        [](auto from, auto to, auto& ctx) {
            std::cout << "Starting command parsing...\n";
        }
    );

    sm.addTransition(
        CommandStateMachine::State::PARSING,
        CommandStateMachine::State::VALIDATING,
        [](auto from, auto to, auto& ctx) {
            std::cout << "Starting validation...\n";
        }
    );

    sm.addTransition(
        CommandStateMachine::State::ERROR,
        CommandStateMachine::State::ERROR,
        [](auto from, auto to, auto& ctx) {
            auto error = std::any_cast<std::string>(ctx.customData);
            std::cerr << "Command failed: " << error << "\n";
        }
    );
}

int main(int argc, char* argv[]) {
    CommandStateMachine sm;
    setupCommandStateMachine(sm);
    sm.process(argc, argv);
    return sm.getCurrentState() == CommandStateMachine::State::COMPLETED ? 0 : 1;
}
