    static std::string generateOptionsTable(const CommandLineParser& parser) {
        std::stringstream table;
        table << "| Option | Description | Default | Required |\n";
        table << "|--------|-------------|---------|----------|\n";

        for (const auto& option : parser.getOptions()) {
