        std::ofstream htmlFile("docs.html");
        htmlFile << htmlDocs;
    }

private:
    // Simple Markdown to HTML conversion (basic implementation)
    static std::string convertMarkdownToHtml(const std::string& markdown) {
        std::string html = markdown;

        // Replace headers
        std::regex h1Regex(R"(^# (.+)$)");
        html = std::regex_replace(html, h1Regex, "<h1>$1</h1>");

        std::regex h2Regex(R"(^## (.+)$)");
        html = std::regex_replace(html, h2Regex, "<h2>$1</h2>");

        // Replace code blocks
        std::regex codeBlockRegex(R"(```(.*?)```)");
        html = std::regex_replace(html, codeBlockRegex, "<pre><code>$1</code></pre>");

        // Replace inline code
        std::regex inlineCodeRegex(R"(`(.*?)`)");;
        html = std::regex_replace(html, inlineCodeRegex, "<code>$1</code>");

        return html;
    }
};

